reactions.activationCode:
await api.addGlobalBonus(reactorToken.actor, {
    id: `hyperawareness`,
    name: "Hyperawareness",
    type: "multi",
    bonuses: [
        {
            type: "difficulty",
            val: 1,
            rollTypes: ["attack"], 
            applyToTargetter: true 
        },
        {
            type: "accuracy",
            val: 1,
            rollTypes: ["check"] 
        }
    ]
}, {
    // expires the bonus at the start of the token's first turn this round
    duration: 'start',
    durationTurns: 0
});

reactions.evaluate:
const currentRound = game.combat?.round ?? 0;
const lastUsedRound = api.getActorFlags(reactorToken.actor, "battle_oracle_round");

if (lastUsedRound === currentRound && currentRound !== 0) return false;

return api.isHostile(reactorToken, triggerData.triggeringToken);

reactions.activationCode:
const ask = await api.askCard({
    title: "Battle Oracle",
    description: `Missed by ${triggerData.triggeringToken.name}! Pull a character 2 spaces within Sensors?`,
    owner: reactorToken,
    yesText: "Pull",
    noText: "Pass"
});

if (!ask.confirmed) return;

// consume the 1/round use
const currentRound = game.combat?.round ?? 0;
await api.addActorFlags(reactorToken.actor, { "battle_oracle_round": currentRound });    

const targets = await api.chooseToken(reactorToken, {
    title: "SELECT PULL TARGET",
    range: 'sensors',
    count: 1,
    includeSelf: true
});

if (!targets || !targets.length) return;

await api.knockBackToken(targets, 2, { 
    triggeringToken: reactorToken,
    title: "PULL",
    description: "Select destination to pull the target to."
});
